(()=>{'use strict';
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
 const en=()=>document.documentElement.lang==='en',t=(ar,eng)=>en()?eng:ar;
 const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const M=v=>Number(v||0).toFixed(2)+' ₪';
 const kinds={wishlist:['هاي ذوقي','My wish list'],look:['تنسيقتي','My look'],occasion:['احجزي إطلالتك','Saved occasion'],poll:['ساعدوني أختار','Help me choose'],group:['طلبية الصحبات','Friends’ basket']};
 const tabs={gifts:['هدايا بميزانيتي','Gifts on a budget'],lists:['قوائمي','My lists'],compare:['محتارة بينهن؟','Compare'],closet:['خزانتي','My wardrobe'],referrals:['إلك ولصاحبتك','Invite a friend'],reviews:['صور وتجارب','Customer stories'],notifications:['تنبيهاتي','My alerts']};
 let panel,currentTab='gifts',cfg={},catalog=[],myLists=[],selected=loadLocal('lf_community_selection',[]),viewList=null,lastFocus,oldOverflow='',requestId=0,currentQuote=null,giftForm=null,swapIndex=-1,swapBundle=null;
 let listDraft={kind:'wishlist',title:'',alerts:false};
 let checkout=loadLocal('lf_community_checkout',null),refCode='',referralCache=null,referralKey='',referralRequest=0;
 const visitor=(()=>{let v=loadLocal('lf_community_visitor','');if(!v){v=crypto.randomUUID()+crypto.randomUUID();persist('lf_community_visitor',v);}return v;})();
 function loadLocal(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
 function persist(k,v){try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,JSON.stringify(v));}catch{}}
 function auth(){return typeof lfToken==='function'&&!!lfToken()}
 async function api(path,method='GET',body){return lfFetch('/api/community'+path,{method,...(body!==undefined?{body:JSON.stringify(body)}:{})});}
 function status(value=''){if(panel)$('#lfCStatus').textContent=value;}
 function content(html){$('#lfCContent').innerHTML=html;status();}
 function busy(){content('<p class="lf-c-empty">'+t('لحظة ونجهّزها إلك…','One moment…')+'</p>');}
 function needAccount(){if(auth())return true;content('<div class="lf-c-empty">'+t('سجّلي دخولك لتحفظي اختياراتك وتلاقيها من أي جهاز.','Sign in to save your picks and find them on any device.')+'<br><button class="lf-c-btn primary" data-c-act="login">'+t('دخول / حساب جديد','Sign in / Create account')+'</button></div>');return false;}
 function product(id){return catalog.find(p=>Number(p.id)===Number(id));}
 function title(p){return en()?(p?.en||p?.name||'Product'):(p?.name||'منتج');}
 function image(p){const raw=p?.image||p?.imageUrl||p?.images?.[0]||'';try{const u=new URL(raw,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'/assets/brand-icon.png'}catch{return '/assets/brand-icon.png'}}
 function options(p){return p?.variants||[];}
 function pick(p,id){return options(p).find(v=>String(v.id)===String(id));}
 function itemPrice(p,id){const v=pick(p,id);return Number(v?.price??p?.price)||0;}
 function stock(p,id){return Number(options(p).length?pick(p,id)?.stock:p?.stock)||0;}
 function firstChoice(p){return options(p).find(v=>Number(v.stock)>0&&(Number(v.price??p.price)>0))?.id||null;}
 function choiceFields(p,prefix){return options(p).length?'<label>'+t('اللون / الخيار','Color / option')+'<select class="lf-c-field" id="'+prefix+'">'+options(p).map(v=>'<option value="'+Number(v.id)+'" '+(Number(v.stock)<=0?'disabled':'')+'>'+E(v.name||v.color)+(Number(v.stock)<=0?t(' — خلص',' — Sold out'):'')+'</option>').join('')+'</select></label>':'';}
 function regionField(id,value='westbank'){return '<label>'+t('منطقة التوصيل','Delivery region')+'<select class="lf-c-field" id="'+id+'">'+[['westbank','الضفة الغربية','West Bank'],['jerusalem','القدس','Jerusalem'],['inside','الداخل','Inside 1948']].map(x=>'<option value="'+x[0]+'" '+(x[0]===value?'selected':'')+'>'+t(x[1],x[2])+'</option>').join('')+'</select></label>';}
 function kindLabel(kind){return kinds[kind]?.[en()?1:0]||kind;}
 function button(action,label,attrs='',primary=false){return '<button type="button" class="lf-c-btn '+(primary?'primary':'')+'" data-c-act="'+action+'" '+attrs+'>'+label+'</button>';}
 function card(p,action='choose-product',label){return '<article class="lf-c-card"><img src="'+E(image(p))+'" alt="'+E(title(p))+'" loading="lazy"><h3>'+E(title(p))+'</h3><span class="lf-c-price">'+(Number(p.price)>0?M(p.price):t('السعر قيد التحديث','Price being updated'))+'</span><br>'+button(action,label||t('اختاري','Choose'),'data-id="'+Number(p.id)+'"')+'</article>';}
 function shareUrl(productId){const u=new URL('/share/product/'+Number(productId),location.origin);if(refCode)u.searchParams.set('ref',refCode);return u.href;}
 function listUrl(token){return new URL('/share/list/'+token,location.origin).href;}
 async function share(text,url,imageFile){
  const bridge=window.LFNativeShare;
  if(bridge?.postMessage){const payload={text,url};if(imageFile)payload.imageData=await new Promise((r,j)=>{const reader=new FileReader();reader.onload=()=>r(reader.result);reader.onerror=j;reader.readAsDataURL(imageFile)});bridge.postMessage(JSON.stringify(payload));return;}
  try{if(imageFile&&navigator.canShare?.({files:[imageFile]})){await navigator.share({files:[imageFile],text,url});return;}if(!imageFile&&navigator.share){await navigator.share({title:'Ladies First',text,url});return;}}catch(e){if(e.name==='AbortError')return;}
  if(imageFile){const href=URL.createObjectURL(imageFile),a=document.createElement('a');a.href=href;a.download=imageFile.name;a.click();setTimeout(()=>URL.revokeObjectURL(href),60000);}
  await copy(url);status(t('الرابط جاهز. أرسليه للشخص اللي بتحبيه.','Your link is ready to share.'));
 }
 async function copy(value){try{await navigator.clipboard.writeText(value);}catch{const el=document.createElement('textarea');el.value=value;document.body.append(el);el.select();document.execCommand('copy');el.remove();}if(typeof showCartNotice==='function')showCartNotice(t('تم نسخ الرابط 🌸','Link copied 🌸'));}
 function shell(){
  if(panel)return;
  panel=document.createElement('div');panel.className='lf-c-overlay';panel.id='lfCommunityPanel';panel.hidden=true;
  panel.innerHTML='<section class="lf-c-panel" role="dialog" aria-modal="true" aria-labelledby="lfCTitle"><header class="lf-c-head"><div><span class="lf-c-kicker">LADIES FIRST • TOGETHER</span><h2 id="lfCTitle"></h2></div><button type="button" data-c-act="close" aria-label="'+t('إغلاق','Close')+'">×</button></header><nav class="lf-c-nav" id="lfCNav" aria-label="'+t('أقسام الحساب والمشاركة','Account and sharing sections')+'"></nav><p class="lf-c-status" id="lfCStatus" role="status" aria-live="polite"></p><div class="lf-c-content" id="lfCContent"></div></section>';
  panel.addEventListener('click',e=>{if(e.target===panel)return close();const b=e.target.closest('[data-c-act]');if(b&&!b.disabled)handle(b).catch(e=>status(e.message||t('تعذر إتمام الخطوة','Unable to complete the action')));});
  panel.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const focusable=$$('button:not([disabled]),input,select,textarea,a[href]',panel).filter(x=>x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
  document.body.append(panel);
 }
 function nav(){const root=$('#lfCNav');root.innerHTML=Object.entries(tabs).map(([key,label])=>button('tab',label[en()?1:0],'data-tab="'+key+'" class="'+(currentTab===key?'active':'')+'"')).join('');$$('button',root).forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));$('#lfCTitle').textContent=t('اختياراتك وأحبابك','Your picks, your people');}
 async function open(tab='gifts'){
  shell();lastFocus=document.activeElement;if(panel.hidden){oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}panel.hidden=false;currentTab=tab;viewList=null;nav();$('#lfCommunityPanel [data-c-act="close"]').focus();await render(tab);
 }
 function close(){if(!panel)return;panel.hidden=true;document.body.style.overflow=oldOverflow;requestId++;lastFocus?.focus?.();}
 async function refresh(){const r=await api('/catalog');catalog=r.products||[];}
 async function render(tab){
  const request=++requestId;currentTab=tab;nav();busy();if(!catalog.length)await refresh();if(request!==requestId)return;
  if(tab==='gifts')return gifts();if(tab==='compare')return compare();if(tab==='reviews')return reviews();if(!needAccount())return;
  if(tab==='lists'){const r=await api('/lists');if(request!==requestId)return;myLists=r.lists;return lists();}
  if(tab==='closet')return closet();if(tab==='referrals')return referrals();if(tab==='notifications')return notifications();
 }
 function gifts(){content('<div class="lf-c-note">'+t('ثلاث اختيارات بميزانية واحدة تشمل القطع والتغليف والبطاقة والتوصيل. بدّلي أي قطعة وشوفي المجموع قبل الدفع.','Gift ideas with products, wrapping, a card and delivery included. Swap a piece and check the total before checkout.')+'</div><form id="lfGiftForm" class="lf-c-form"><label>'+t('ميزانيتك بالشيكل','Budget in ILS')+'<input id="lfGiftBudget" class="lf-c-field" type="number" min="1" max="100000" value="250"></label>'+regionField('lfGiftRegion')+'<label>'+t('المناسبة','Occasion')+'<select id="lfGiftOccasion" class="lf-c-field"><option>'+t('هدية','Gift')+'</option><option>'+t('عيد ميلاد','Birthday')+'</option><option>'+t('نجاح','Graduation')+'</option><option>'+t('عيد الأم','Mother’s Day')+'</option></select></label><label>'+t('التغليف لكل قطعة','Wrapping per item')+'<select class="lf-c-field" id="lfGiftPackaging"><option value="">'+t('بدون تغليف — 0 ₪','No wrapping — 0 ILS')+'</option>'+(cfg.packaging||[]).filter(x=>x.active!==false).map(x=>'<option value="'+E(x.id)+'">'+E(en()?(x.nameEn||x.nameAr):(x.nameAr||x.nameEn))+' — '+M(x.price)+'</option>').join('')+'</select></label><label>'+t('اسم المستلمة / المستلم على البطاقة','Recipient on the card')+'<input id="lfGiftRecipient" class="lf-c-field" maxlength="32" required></label><label>'+t('صيغة البطاقة','Card wording')+'<select id="lfGiftGender" class="lf-c-field"><option value="f">'+t('لها','For her')+'</option><option value="m">'+t('له','For him')+'</option></select></label><label>'+t('المُهدي — اختياري','Sender — optional')+'<input id="lfGiftSender" class="lf-c-field" maxlength="32"></label><label class="wide">'+t('رسالة البطاقة — حتى 12 كلمة','Card message — up to 12 words')+'<input id="lfGiftMessage" class="lf-c-field" value="'+t('كل لحظة وإنتِ بألف خير','Wishing you beautiful moments, always')+'" maxlength="180"></label><div class="wide">'+button('gift-find',t('جهّزيلي الخيارات','Find my gifts'),'',true)+'</div></form><div id="lfGiftResults"></div>');}
 async function giftFind(){
  const recipient=$('#lfGiftRecipient').value.trim(),message=$('#lfGiftMessage').value.trim();if(!recipient||!message||message.split(/\s+/).length>12)throw Error(t('أضيفي اسم المستلم ورسالة حتى 12 كلمة','Add the recipient and a message of up to 12 words'));
  giftForm={budget:Number($('#lfGiftBudget').value),region:$('#lfGiftRegion').value,occasion:$('#lfGiftOccasion').value,packagingId:$('#lfGiftPackaging').value,giftCard:true,gender:$('#lfGiftGender').value,recipient,sender:$('#lfGiftSender').value.trim(),message};
  status(t('عم ننسّق الخيارات…','Finding your gift ideas…'));const r=await api('/gift-bundles','POST',giftForm);status();window.LFCommunity.giftBundles=r.bundles;
  $('#lfGiftResults').innerHTML=r.bundles.length?'<div class="lf-c-cards">'+r.bundles.map((q,index)=>'<article class="lf-c-card"><h3>'+t('اقتراح','Gift idea')+' '+(index+1)+'</h3>'+quoteLines(q,index)+'<div class="lf-c-note">'+t('القطع','Products')+': '+M(q.subtotal)+'<br>'+t('التغليف','Wrapping')+': '+M(q.packaging)+' · '+t('البطاقة','Card')+': '+M(q.giftCard)+'<br>'+t('التوصيل','Delivery')+': '+M(q.shipping)+'</div><p class="lf-c-price">'+M(q.total)+'</p>'+button('gift-buy',t('اختاري هالهدية','Choose this gift'),'data-index="'+index+'"',true)+'</article>').join('')+'</div>':'<p class="lf-c-empty">'+t('ما لقينا خيارًا متوفرًا ضمن الميزانية الشاملة. جرّبي ميزانية أعلى أو تغليفًا آخر.','No available gift fits the full budget. Try a larger budget or different wrapping.')+'</p>';
 }
 function quoteLines(q,index){return q.items.map((i,j)=>'<div class="lf-c-line"><img src="'+E(image(i.product))+'" alt=""><div><b>'+E(title(i.product))+'</b><p>'+E(i.variantName||'')+' · '+M(i.price)+'</p>'+button('gift-swap',t('بدّلي القطعة','Swap item'),'data-index="'+index+'" data-item="'+j+'"')+'</div></div>').join('');}
 function lists(){content('<div class="lf-c-row between"><p>'+t('قوائمك محفوظة بحسابك. شاركي الرابط مع الأشخاص اللي بتختاريهم.','Your lists are saved to your account. Share links with people you choose.')+'</p>'+button('new-list',t('قائمة أو تصويت جديد','New list or poll'),'',true)+'</div><div class="lf-c-cards">'+myLists.map(l=>'<article class="lf-c-card"><span class="lf-c-pill">'+kindLabel(l.kind)+'</span><h3>'+E(l.title)+'</h3><p>'+l.items.length+' '+t('قطعة','items')+'</p>'+button('view-list',t('افتحي','Open'),'data-token="'+l.token+'"')+button('share-list',t('شاركي','Share'),'data-token="'+l.token+'"')+'</article>').join('')+'</div>'+(myLists.length?'':'<p class="lf-c-empty">'+t('ابدئي بقائمة أمنيات، تنسيقة، أو طلبية تجمعك بصحباتك.','Start a wish list, a look, or a basket with friends.')+'</p>'));}
 function newList(kind=listDraft.kind||'wishlist'){
  if(!needAccount())return;
  content('<form class="lf-c-form"><label>'+t('نوع القائمة','List type')+'<select id="lfNewKind" class="lf-c-field">'+Object.keys(kinds).map(k=>'<option value="'+k+'" '+(k===kind?'selected':'')+'>'+kindLabel(k)+'</option>').join('')+'</select></label><label>'+t('اسم تختاريه إلك','Give it a name')+'<input id="lfNewTitle" class="lf-c-field" maxlength="80" value="'+E(listDraft.title)+'" placeholder="'+t('مثلاً: هدية أمي أو إطلالة العيد','For example: Mum’s gift or Eid look')+'"></label><label class="wide lf-c-check"><input type="checkbox" id="lfNewAlerts" '+(listDraft.alerts?'checked':'')+'>'+t('تنبيه داخل حسابي إذا انخفض السعر أو بقيت قطع قليلة','In-account alerts for price drops or low stock')+'</label></form><p>'+t('اختياراتك الحالية','Your current picks')+': '+selected.length+' / 30</p><div id="lfSelection">'+selectionHtml()+'</div>'+button('pick-for-list',t('أضيفي قطع','Add products'))+' '+button('save-list',t('احفظي القائمة','Save list'),'',true)+'<p class="lf-c-note">'+t('قائمة الأمنيات تخفي الهدايا التي حُجزت بطلب. التصويت يحتاج قطعتين أو ثلاث. حفظ الإطلالة والسلة المشتركة لا يحجزان المخزون.','Wish lists hide gifts already claimed in an order. Polls need two or three choices. Saved looks and shared baskets do not reserve stock.')+'</p>');
 }
 function selectionHtml(){return selected.map((i,index)=>{const p=product(i.productId);return p?'<div class="lf-c-line"><img src="'+E(image(p))+'" alt=""><div><b>'+E(title(p))+'</b><p>'+E(pick(p,i.variantId)?.name||'')+' × '+i.quantity+'</p></div>'+button('remove-selection','×','data-index="'+index+'" aria-label="'+t('إزالة','Remove')+'"')+'</div>':'';}).join('');}
 function productPicker(action,extra={}){
  window.LFCommunity.picker={action,...extra};
  content('<label>'+t('ابحثي عن قطعة','Find a product')+'<input class="lf-c-field" id="lfPickerSearch" type="search" autocomplete="off"></label><div class="lf-c-cards" id="lfPickerResults"></div>');
  const render=()=>{const query=$('#lfPickerSearch').value.trim().toLowerCase();$('#lfPickerResults').innerHTML=catalog.filter(p=>Number(p.price)>0||options(p).some(v=>Number(v.price)>0)).filter(p=>!query||(p.name+' '+(p.brand||'')).toLowerCase().includes(query)).slice(0,36).map(p=>card(p)).join('');};$('#lfPickerSearch').addEventListener('input',render);render();
 }
 function chooseProduct(id){const p=product(id);if(!p)return;const context=window.LFCommunity.picker||{action:'selection'};window.LFCommunity.pendingProduct=p;content('<div class="lf-c-row"><img style="height:170px;max-width:45%;object-fit:contain" src="'+E(image(p))+'" alt=""><div><h3>'+E(title(p))+'</h3><span class="lf-c-price">'+M(p.price)+'</span></div></div><div class="lf-c-form">'+choiceFields(p,'lfPickVariant')+'<label>'+t('الكمية','Quantity')+'<input id="lfPickQty" class="lf-c-field" type="number" min="1" max="20" value="1"></label>'+(context.action==='group'?'<label>'+t('اسم يظهر لصاحباتك — لا تضيفي رقم هاتف','Display name for the group — no phone numbers')+'<input id="lfContributor" class="lf-c-field" maxlength="30"></label>':'')+'</div>'+button('confirm-product',t('اعتمدي الاختيار','Confirm choice'),'',true));const select=$('#lfPickVariant');if(select)select.value=String(firstChoice(p)||'');}
 async function confirmProduct(){const p=window.LFCommunity.pendingProduct,context=window.LFCommunity.picker||{action:'selection'},variantId=Number($('#lfPickVariant')?.value)||null,quantity=Number($('#lfPickQty').value);if(quantity<1||quantity>20||!Number.isInteger(quantity)||stock(p,variantId)<quantity||itemPrice(p,variantId)<=0)throw Error(t('الكمية أو اللون غير متوفر','This quantity or option is unavailable'));const item={productId:Number(p.id),variantId,quantity};
  if(context.action==='group'){await api('/shared/'+context.token+'/items','POST',{...item,visitorKey:visitor,contributorName:$('#lfContributor')?.value||t('مشاركة','Guest')});return viewShared(context.token);}
  if(context.action==='existing'){await api('/lists/'+context.id+'/items','POST',item);return viewShared(context.token);}
  if(context.action==='swap'){const q=window.LFCommunity.giftBundles[context.index],items=q.items.map((x,j)=>j===context.item?{...item,packagingId:giftForm.packagingId}:{productId:x.productId,variantId:x.variantId,quantity:x.quantity,packagingId:x.packagingId});const r=await api('/quote','POST',{...giftForm,items});if(!r.quote.withinBudget)throw Error(t('هذا الاختيار يتجاوز ميزانيتك: ','This exceeds your budget: ')+M(r.quote.total));window.LFCommunity.giftBundles[context.index]=r.quote;return giftResultsAfterSwap();}
  if(selected.some(i=>i.productId===item.productId&&i.variantId===item.variantId))throw Error(t('القطعة موجودة ضمن اختياراتك','This item is already selected'));if(selected.length>=30)throw Error(t('الحد الأقصى 30 قطعة','Choose up to 30 items'));selected.push(item);persist('lf_community_selection',selected);if(context.action==='compare')return compare();newList(context.kind||'wishlist');
 }
 function giftResultsAfterSwap(){const bundles=window.LFCommunity.giftBundles;content('<h3>'+t('خيارات هديتك بعد التعديل','Your updated gift ideas')+'</h3><div class="lf-c-cards">'+bundles.map((q,index)=>'<article class="lf-c-card">'+quoteLines(q,index)+'<p>'+t('شامل التغليف والبطاقة والتوصيل','Includes wrapping, card and delivery')+'</p><p class="lf-c-price">'+M(q.total)+'</p>'+button('gift-buy',t('اختاري هالهدية','Choose this gift'),'data-index="'+index+'"',true)+'</article>').join('')+'</div>');}
 async function saveList(){const kind=$('#lfNewKind').value,title=$('#lfNewTitle').value.trim();if(!title)throw Error(t('سمّي القائمة','Give your list a name'));const r=await api('/lists','POST',{kind,title,alerts:$('#lfNewAlerts').checked,items:selected});selected=[];listDraft={kind:'wishlist',title:'',alerts:false};persist('lf_community_selection',selected);await viewShared(r.list.token);}
 async function viewShared(token){shell();if(panel.hidden){lastFocus=document.activeElement;oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';panel.hidden=false;}nav();busy();const r=await api('/shared/'+token);viewList=r.list;renderShared();}
 function renderShared(){const l=viewList;if(!l)return;
  const poll=l.kind==='poll',group=l.kind==='group';
  content('<div class="lf-c-row between"><div><span class="lf-c-pill">'+kindLabel(l.kind)+'</span><h3>'+E(l.title)+'</h3></div>'+button('share-list',t('شاركي الرابط','Share link'),'data-token="'+l.token+'"',true)+'</div><p class="lf-c-note">'+(poll?t('صوت واحد لكل متصفح، ويمكن تغييره. التعليقات تظهر لكل من يحمل الرابط.','One vote per browser; you can change it. Comments are visible to people with the link.'):group?t('كل مشاركة تضيف قطعها باسم تختاره. صاحبة الطلبية تدفع الطلب كاملًا، بعنوان توصيل واحد. القطع لا تُحجز حتى إتمام الطلب.','Everyone adds their picks under a display name. The organizer places and pays for one order to one address. Stock is not reserved until checkout.'):t('الرابط خاص بمن تشاركينه معهم. لا يعرض رقم هاتف أو عنوانًا.','Share this private link with people you choose. It never displays a phone number or address.'))+'</p>'+l.items.map(i=>'<div class="lf-c-line">'+(!poll&&i.available&&!i.claimed?'<input class="lfCItemCheck" type="checkbox" value="'+i.id+'" checked aria-label="'+t('اختيار القطعة','Select item')+'">':'')+'<img src="'+E(image(i.product))+'" alt=""><div><b>'+E(title(i.product))+'</b><p>'+E(i.variantName)+' × '+i.quantity+' · '+(i.price>0?M(i.price):t('غير متوفر','Unavailable'))+'</p>'+(i.contributorName?'<p>'+t('اختيار: ','Selected by: ')+E(i.contributorName)+'</p>':'')+(i.claimed?'<span class="lf-c-pill">'+t('اختيرت كهدية','Claimed as a gift')+'</span>':'')+(poll?'<span class="lf-c-pill">'+i.votes+' '+t('صوت','votes')+'</span>':'')+'</div>'+(poll?button('vote',t('هذا اختياري','My choice'),'data-id="'+i.id+'"'):button('product',t('التفاصيل','Details'),'data-id="'+i.productId+'"'))+(l.own||group?button('delete-list-item','×','data-id="'+i.id+'" aria-label="'+t('إزالة اختيارك','Remove your pick')+'"'):'')+'</div>').join('')+(l.items.length?'':'<div class="lf-c-empty">'+t('ما في قطع متاحة في القائمة حاليًا.','There are no available items in this list right now.')+'</div>')+
   (poll?'<label>'+t('رأيك — اختياري','Your comment — optional')+'<input id="lfVoteComment" class="lf-c-field" maxlength="180"></label>'+l.comments.map(c=>'<p class="lf-c-ballot">'+E(c)+'</p>').join(''):'<div class="lf-c-row">'+(group&&!l.locked?button('add-group',t('أضيفي اختياراتك','Add your picks')):l.own?button('add-existing',t('أضيفي قطعة','Add an item')):'')+(!group||l.own?button('buy-list',t('أضيفي المحدد للسلة','Add selected to basket'),'',true):'')+'</div>')+
   (l.kind==='wishlist'&&l.privateDeliveryAvailable?'<label class="lf-c-check lf-c-note"><input type="checkbox" id="lfPrivateGift">'+t('إرسال الهدية لصاحبة القائمة بعنوانها المحمي','Send the gift to the list owner’s private address')+'</label>':'')+
   (group?'<p class="lf-c-note">'+t('بعد اختيار منطقة التوصيل في الدفع، يمكنك تقسيم رسم التوصيل بالتساوي بين المشاركات. هذا تقسيم للمعلومة، وليس تحصيل دفعات منفصلة.','Delivery can be shared equally between contributors. This is a cost estimate; it does not collect separate payments.')+'</p><div class="lf-c-form">'+regionField('lfGroupRegion')+'</div>'+button('group-split',t('احسبي حصة كل مشاركة','Calculate each person’s share'))+'<div id="lfGroupSplit"></div>':'')+
   (l.own?'<div class="lf-community-tools">'+(l.kind==='wishlist'?button('delivery',t('العنوان الخاص للهدايا','Private gift address')):'')+button('toggle-alerts',l.alerts?t('إيقاف التنبيهات','Turn alerts off'):t('تنبيه للسعر والمخزون','Price and stock alerts'))+button('revoke-list',t('إلغاء الرابط والقائمة','Revoke link and list'))+'</div>':''));
 }
 function privateDelivery(){content('<h3>'+t('عنوان لا يراه المُهدي','An address hidden from the gift buyer')+'</h3><p class="lf-c-note">'+t('يستخدمه المتجر للتوصيل فقط. من يفتح الرابط لا يرى الهاتف أو العنوان، حتى في سجل طلبه.','The store uses this only for delivery. Link visitors and gift buyers cannot see the phone number or address, including in their order history.')+'</p><div class="lf-c-form"><label>'+t('اسم المستلمة','Recipient name')+'<input id="lfDeliveryName" class="lf-c-field" maxlength="100" autocomplete="name"></label><label>'+t('الهاتف للتوصيل','Delivery phone')+'<input id="lfDeliveryPhone" class="lf-c-field" maxlength="25" type="tel"></label><label class="wide">'+t('العنوان','Address')+'<textarea id="lfDeliveryAddress" class="lf-c-field" maxlength="500"></textarea></label>'+regionField('lfDeliveryRegion')+'<label class="wide lf-c-check"><input id="lfDeliveryConsent" type="checkbox">'+t('أوافق على استخدام بياناتي لإيصال الهدايا التي تُطلب من قائمتي','I consent to using my details to deliver gifts ordered from my list')+'</label></div>'+button('save-delivery',t('احفظي العنوان الخاص','Save private address'),'',true)+' '+button('remove-delivery',t('أوقفي العنوان الخاص','Disable private delivery')));}
 function compare(){const items=selected.slice(0,3).map(i=>({i,p:product(i.productId)})).filter(x=>x.p);content('<p>'+t('اختاري قطعتين أو ثلاث. المقارنة تستخدم تفاصيل الأصناف المسجلة فقط.','Choose two or three items. Comparisons use only the recorded product details.')+'</p>'+button('pick-compare',t('أضيفي قطعة للمقارنة','Add a product'))+'<div class="lf-c-compare"><table><thead><tr><th>'+t('المقارنة','Compare')+'</th>'+items.map(({p,i},index)=>'<th><img src="'+E(image(p))+'" alt=""><br>'+E(title(p))+'<br>'+button('remove-compare',t('إزالة','Remove'),'data-index="'+index+'"')+'</th>').join('')+'</tr></thead><tbody>'+[[t('السعر','Price'),({p,i})=>M(itemPrice(p,i.variantId))],[t('البراند','Brand'),({p})=>E(p.brand||t('غير مسجل','Not provided'))],[t('الخامة / المقاس','Material / size'),({p,i})=>E([p.metadata?.material,pick(p,i.variantId)?.size].filter(Boolean).join(' / ')||t('غير مسجل','Not provided'))],[t('الوصف','Description'),({p})=>E(p.description||t('غير مسجل','Not provided'))],[t('التوفر','Availability'),({p,i})=>stock(p,i.variantId)>0?t('متوفر','Available'):t('نفد','Sold out')]].map(([label,fn])=>'<tr><th>'+label+'</th>'+items.map(x=>'<td>'+fn(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="lf-c-form"><label>'+t('1. ميزانيتك للقطعة؟','1. Your budget per item?')+'<input class="lf-c-field" id="lfCompareBudget" type="number" min="1" value="250"></label><label>'+t('2. لأي استخدام؟','2. What is it for?')+'<select class="lf-c-field" id="lfCompareOccasion"><option>'+t('يومي','Everyday')+'</option><option>'+t('هدية','Gift')+'</option><option>'+t('سهرة','Evening')+'</option></select></label></div>'+button('compare-advice',t('شو بترشحيلي يا نايا؟','Naia, which would you pick?'),'',true)+'<div id="lfCompareAdvice"></div>'+button('new-poll',t('اسألي صحباتك بتصويت خاص','Ask friends in a private poll')));}
 async function closet(){const r=await api('/closet'),visible=r.items.filter(i=>!i.hidden);content('<p class="lf-c-note">'+t('خزانتك تجمع مشترياتك التي تم تسليمها. أخفي قطع الهدايا من اقتراحاتك بأي وقت.','Your wardrobe contains delivered purchases. You can hide gifts from your recommendations at any time.')+'</p>'+r.items.map(i=>'<div class="lf-c-line"><img src="'+E(image(i))+'" alt=""><div><b>'+E(i.name)+'</b><p>'+E(i.variant||'')+(i.hidden?' · '+t('مخفية من الاقتراحات','Hidden from suggestions'):'')+'</p></div>'+button('closet-hide',i.hidden?t('إظهار','Show'):t('هدية / إخفاء','Gift / Hide'),'data-id="'+i.id+'" data-hidden="'+(!i.hidden)+'"')+button('write-review',t('شاركي تجربتك','Review it'),'data-id="'+i.productId+'"')+'</div>').join('')+(!r.items.length?'<p class="lf-c-empty">'+t('بعد تسليم أول طلب، بتلاقي مشترياتك هون.','Your purchases will appear after your first order is delivered.')+'</p>':'')+'<h3>'+t('بيناسب القطع اللي عندك','Pairs with your wardrobe')+'</h3><div class="lf-c-cards">'+catalog.filter(p=>!visible.some(i=>Number(i.productId)===Number(p.id))).filter(p=>Number(p.price)>0&&((p.category||'').match(/اكسسوار|إكسسوار|accessor/i)||visible.some(i=>{const bought=product(i.productId),tags=String(bought?.metadata?.styleTags||'').split(/[,،]/).map(x=>x.trim()).filter(Boolean);return tags.some(tag=>String(p.metadata?.styleTags||'').includes(tag))}))).slice(0,6).map(p=>card(p,'product',t('شوفي القطعة','View item'))).join('')+'</div>');}
 async function referrals(){const r=await api('/referral');refCode=r.code;persist('lf_referral_code',refCode);const s=r.settings,u=new URL('/',location.origin);u.searchParams.set('ref',r.code);content('<h3>'+t('إلك ولصاحبتك','A little something for both of you')+'</h3><div class="lf-c-note">'+(s.referralsEnabled?t('صاحبتك تحصل على ','Your friend gets ')+s.referralPercent+'% '+t('خصم على أول طلب، حتى ','off her first order, up to ')+M(s.referralMaximum)+t('، بحد أدنى ',' with a minimum of ')+M(s.referralMinimum)+'.<br>'+t('وإلك ','You get ')+s.referralPoints+' '+t('نقطة بعد تسليم طلبها. لا يجمع مع كوبون آخر.','points after her order is delivered. Cannot be combined with another coupon.'):t('برنامج الدعوات متوقف حاليًا.','The referral program is currently paused.'))+'</div><p class="lf-c-link">'+E(u.href)+'</p>'+button('share-referral',t('ابعتي رابطك','Share your link'),'data-url="'+E(u.href)+'"',true)+'<div class="lf-c-cards">'+r.summary.map(x=>'<div class="lf-c-card"><h3>'+({pending:t('بانتظار التسليم','Awaiting delivery'),rewarded:t('دعوات مكتملة','Completed referrals'),cancelled:t('طلبات ملغاة','Cancelled orders')}[x.state]||E(x.state))+'</h3><p>'+x.count+'</p><small>'+Number(x.points||0)+' '+t('نقطة','points')+'</small></div>').join('')+'</div>');}
 async function notifications(){const r=await api('/notifications');content('<p class="lf-c-note">'+t('تنبيهات داخل الحساب للقوائم التي فعّلتِ تنبيهها. لا تُرسل رسائل أو إشعارات خارج التطبيق.','In-account alerts for lists you opted into. These do not send messages or notifications outside the app.')+'</p>'+r.notifications.map(n=>'<div class="lf-c-ballot">'+E(n.message)+' '+(!n.seen?'<span class="lf-c-pill">'+t('جديد','New')+'</span>':'')+button('product',t('شوفي القطعة','View item'),'data-id="'+n.productId+'"')+'</div>').join('')+(!r.notifications.length?'<p class="lf-c-empty">'+t('ما في تنبيهات جديدة.','No alerts yet.')+'</p>':'')+button('read-notifications',t('تحديد الكل كمقروء','Mark all read')));}
 async function reviews(productId,reviewId){const params=new URLSearchParams();if(productId)params.set('productId',productId);if(reviewId)params.set('reviewId',reviewId);const r=await api('/reviews?'+params.toString());content('<p class="lf-c-note">'+t('تجارب مشتريات تم استلامها. تُنشر الصور بالموافقة وبعد المراجعة؛ التقييم الإيجابي ليس شرطًا للنشر أو المكافأة.','Stories from delivered purchases. Photos require consent and moderation; positive ratings are not required for publication or rewards.')+'</p>'+button('my-reviews',t('تقييماتي وحالة نشرها','My reviews and publication status'))+'<div class="lf-c-cards">'+r.reviews.map(r=>'<article class="lf-c-card">'+(r.hasImage?'<img class="lf-c-photo" src="/api/community/reviews/'+r.id+'/image" alt="'+t('صورة تجربة شراء بموافقة صاحبتها','Customer purchase photo shared with consent')+'">':'')+'<p class="lf-c-stars">'+'★'.repeat(r.rating)+'☆'.repeat(5-r.rating)+'</p><b>'+E(r.displayName)+'</b><p>'+E(r.body)+'</p><small>'+E(r.productName)+'</small><br>'+button('share-review',t('شاركي التجربة','Share story'),'data-id="'+r.id+'" data-product="'+r.productId+'"')+button('product',t('المنتج','View product'),'data-id="'+r.productId+'"')+'</article>').join('')+'</div>'+(!r.reviews.length?'<p class="lf-c-empty">'+t('التجارب المعتمدة بتظهر هون بعد موافقة أصحابها.','Approved customer stories appear here after consent.')+'</p>':''));}
 function writeReview(id){if(!needAccount())return;const p=product(id);window.LFCommunity.reviewProduct=id;content('<h3>'+E(title(p))+'</h3><div class="lf-c-form"><label>'+t('اسم عرض تختاريه','Your public display name')+'<input class="lf-c-field" id="lfReviewName" maxlength="40" value="'+t('زبونة Ladies First','Ladies First customer')+'"></label><label>'+t('تقييمك','Your rating')+'<select id="lfReviewRating" class="lf-c-field">'+[5,4,3,2,1].map(n=>'<option value="'+n+'">'+'★'.repeat(n)+'</option>').join('')+'</select></label><label class="wide">'+t('احكيلنا تجربتك','Tell us about your purchase')+'<textarea id="lfReviewBody" class="lf-c-field" maxlength="800"></textarea></label><label class="wide">'+t('صورة — اختياري. لا تضيفي أشخاصًا دون موافقتهم','Photo — optional. Do not include people without their consent')+'<input type="file" id="lfReviewImage" class="lf-c-field" accept="image/png,image/jpeg,image/webp"></label><label class="wide lf-c-check"><input type="checkbox" id="lfReviewConsent">'+t('أوافق على نشر النص والصورة واسم العرض في المتجر','I consent to publishing this text, photo and display name in the store')+'</label></div>'+button('submit-review',t('أرسلي للمراجعة','Submit for moderation'),'',true));}
 async function photoData(file){if(!file)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error(t('اختاري صورة PNG أو JPG أو WebP بحجم أقل من 12 ميجابايت','Choose PNG, JPG or WebP under 12 MB'));const url=URL.createObjectURL(file);try{const img=await new Promise((r,j)=>{const i=new Image();i.onload=()=>r(i);i.onerror=j;i.src=url});const factor=Math.min(1,1400/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*factor);c.height=Math.round(img.height*factor);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.82);}finally{URL.revokeObjectURL(url)}}
 async function installCart(items,context,gift){
  if(typeof cart==='undefined')return;const normalized=items.map(i=>{const p=products.find(p=>Number(p.id)===Number(i.productId));if(!p)throw Error(t('حدّثي المتجر لإظهار القطعة','Refresh the store to load this item'));const v=(p.variants||[]).find(v=>String(v.id)===String(i.variantId));if(i.variantId&&!v)throw Error(t('اللون تغير؛ حدّثي القائمة','This option changed; refresh the list'));return {id:p.id,qty:Number(i.quantity)||1,variant:v?.name||v?.color||'',packagingId:i.packagingId||''};});
  if(cart.length&&!confirm(t('نستبدل السلة الحالية باختيارات هذه القائمة؟','Replace your current basket with these picks?')))return;
  const merged=new Map();for(const line of normalized){const key=line.id+':'+line.variant+':'+line.packagingId;if(merged.has(key))merged.get(key).qty+=line.qty;else merged.set(key,line);}cart=[...merged.values()];save('lf_cart',cart);checkout=context;persist('lf_community_checkout',checkout);
  if(gift){setGiftCardDraft(gift);}else setGiftCardDraft(null);
  close();renderCart();updateCount();await openCart();openCheckoutForm();decorateCart();
  const region=$('#shippingRegion');if(region&&context?.region){region.value=context.region;if(context.privateDelivery)region.disabled=true;updateCheckoutTotal();}
 }
 async function buyList(){const l=viewList,ids=$$('.lfCItemCheck:checked').map(x=>x.value),items=l.items.filter(i=>ids.includes(i.id)&&i.available&&!i.claimed);if(!items.length)throw Error(t('اختاري قطعة متوفرة','Choose an available item'));const privateDelivery=$('#lfPrivateGift')?.checked===true;await installCart(items,{token:l.token,itemIds:items.map(i=>i.id),privateDelivery,title:l.title,region:privateDelivery?l.deliveryRegion:null});}
 function decorateCart(){const root=$('#cart');if(!root)return;$('#lfCommunityCartBanner')?.remove();if(checkout&&typeof cart!=='undefined'&&cart.length){const banner=document.createElement('div');banner.id='lfCommunityCartBanner';banner.className='lf-c-cart-banner';banner.textContent=checkout.title+' — '+(checkout.privateDelivery?t('الهدية تُرسل للعنوان الخاص المحمي. أدخلي بياناتك للتواصل بشأن الطلب.','The gift goes to the private recipient address. Enter your own contact details for the purchase.'):t('اختيارات من قائمة مشتركة. تغيير القطع يتطلب تحديث القائمة.','Picks from a shared list. Update the list before changing items.'));const clear=document.createElement('button');clear.className='lf-c-btn';clear.type='button';clear.textContent=t('متابعة كسلة عادية','Continue as a normal basket');clear.onclick=()=>{checkout=null;persist('lf_community_checkout',null);renderCart()};banner.append(document.createElement('br'),clear);root.prepend(banner);}}
 function referralCoupon(subtotal){if(!auth()||!referralCache||Math.abs(referralCache.subtotal-subtotal)>.01||!referralCache.discount)return null;return {type:'fixed',value:referralCache.discount,code:'',isReferral:true};}
 async function refreshReferral(){const incoming=loadLocal('lf_referral_incoming',null);if(!incoming||incoming.expires<Date.now()||!auth())return;const subtotal=cartMerchandiseSubtotal(),key=[incoming.code,subtotal,typeof couponCode!=='undefined'?couponCode:'',lfToken()].join(':');if(key===referralKey)return;referralKey=key;const request=++referralRequest;try{const r=await api('/referral/quote','POST',{code:incoming.code,subtotal,couponCode:typeof couponCode!=='undefined'?couponCode:''});if(request!==referralRequest)return;referralCache={subtotal,discount:r.discount};renderCart();}catch{if(request===referralRequest)referralCache=null;}}
 async function story(id){const p=product(id);if(!p)return;window.LFCommunity.storyProduct=id;content('<h3>'+t('بطاقة جاهزة للستوري','A story card ready to share')+'</h3><div class="lf-c-form"><label>'+t('عبارتك','Your caption')+'<select id="lfStoryCaption" class="lf-c-field"><option>'+t('هاي دخلت مزاجي 😍','I’m loving this 😍')+'</option><option>'+t('مين يهديني إياها؟ 🎁','Who’s getting me this? 🎁')+'</option><option>'+t('ذوقي من Ladies First','My pick from Ladies First')+'</option></select></label></div><canvas id="lfStoryCanvas" width="1080" height="1920" style="width:min(300px,100%);height:auto;border-radius:18px;display:block;margin:12px auto"></canvas>'+button('share-story',t('احفظي / شاركي البطاقة','Save / share card'),'',true)+' '+button('copy-product-link',t('انسخي رابط المنتج','Copy product link'),'data-id="'+id+'"')+'<p class="lf-c-note">'+t('السعر على البطاقة وقت المشاركة؛ السعر المعتمد دائمًا داخل المتجر. بعد حفظ الصورة أضيفي رابط المنتج للستوري.','The card shows the price at sharing time; the store has the current price. Add the product link to your story after saving the image.')+'</p>');$('#lfStoryCaption').addEventListener('change',()=>drawStory(p));await drawStory(p);}
 async function drawStory(p){const canvas=$('#lfStoryCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.fillStyle='#fbf4ec';ctx.fillRect(0,0,1080,1920);const gradient=ctx.createLinearGradient(0,0,1080,1920);gradient.addColorStop(0,'#63345e');gradient.addColorStop(1,'#b47998');ctx.fillStyle=gradient;ctx.fillRect(0,0,1080,270);ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='bold 74px Georgia';ctx.fillText('Ladies First',540,130);ctx.font='34px Arial';ctx.fillText(t('لأنك تستحقين','Because you deserve it'),540,205);try{const logo=await new Promise((r,j)=>{const i=new Image();i.onload=()=>r(i);i.onerror=j;i.src='/assets/brand-icon.png';});ctx.drawImage(logo,70,60,145,145);}catch{}ctx.fillStyle='#fff';ctx.fillRect(70,345,940,960);try{const img=await new Promise((r,j)=>{const i=new Image();i.crossOrigin='anonymous';i.onload=()=>r(i);i.onerror=j;i.src=image(p)});const factor=Math.min(850/img.width,850/img.height),w=img.width*factor,h=img.height*factor;ctx.drawImage(img,(1080-w)/2,390+(850-h)/2,w,h);}catch{ctx.fillStyle='#63345e';ctx.font='64px Georgia';ctx.fillText('Ladies First',540,850);}ctx.fillStyle='#63345e';ctx.direction=en()?'ltr':'rtl';ctx.font='bold 48px Arial';const words=title(p).split(/\s+/);let line='',y=1400;for(const word of words){if(ctx.measureText(line+' '+word).width>900){ctx.fillText(line,540,y);line=word;y+=64;}else line+=(line?' ':'')+word;}ctx.fillText(line,540,y);ctx.font='bold 65px Arial';ctx.fillText(Number(p.price)>0?M(p.price):t('السعر قيد التحديث','Price being updated'),540,1585);ctx.font='42px Arial';ctx.fillText($('#lfStoryCaption')?.value||'',540,1700);ctx.font='30px Arial';ctx.fillStyle='#8b6c80';ctx.direction='ltr';ctx.fillText(location.host+' • #'+p.id,540,1805);ctx.font='25px Arial';ctx.fillText(new Intl.DateTimeFormat(en()?'en':'ar-PS').format(new Date()),540,1855);}
 function productTools(id){if(!cfg.settings?.enabled)return;const root=$('#modalBody');if(!root)return;$('#lfCommunityProductTools')?.remove();const bar=document.createElement('div');bar.id='lfCommunityProductTools';bar.className='lf-community-tools';bar.innerHTML=[['share-product',t('↗ شاركي','↗ Share')],['hint-product',t('🎁 تلميحة هدية','🎁 Gift hint')],['story-product',t('📸 ستوري','📸 Story card')],['save-product',t('♡ لقائمتي','♡ Save to list')],['compare-product',t('⚖ مقارنة','⚖ Compare')],['product-reviews',t('★ التجارب','★ Reviews')]].map(([act,label])=>button(act,label,'data-id="'+Number(id)+'"')).join('');bar.addEventListener('click',e=>{const b=e.target.closest('[data-c-act]');if(b)handle(b).catch(e=>showCartNotice(e.message));});root.querySelector('.modalGrid>div:last-child')?.append(bar);}
 function mount(){if(!cfg.settings?.enabled)return;let root=$('#lfCommunityHome');if(!root){root=document.createElement('section');root.className='lf-community-home';root.id='lfCommunityHome';const target=$('#storeDiscoveryIdeas');if(target)target.after(root);else $('main')?.prepend(root);}root.innerHTML='<h2>'+t('إلك وللي بتحبيهم','For you and your favorite people')+'</h2><p>'+t('هدية، تنسيقة، رأي صاحبتك… كل اختياراتك بمكان واحد.','Gifts, outfits and a friend’s opinion — all your picks in one place.')+'</p><div class="lf-community-grid">'+[['gifts','🎁','هدية بميزانيتي','Gifts on a budget'],['lists','💌','قوائمي والصحبات','My lists & friends'],['compare','⚖️','ساعديني أختار','Help me choose'],['closet','👛','خزانتي','My wardrobe'],['referrals','🎟️','إلك ولصاحبتك','Invite a friend'],['reviews','📸','تجاربكم','Your stories']].map(([tab,icon,ar,eng])=>'<button class="lf-community-tile" data-tab="'+tab+'"><span aria-hidden="true">'+icon+'</span>'+t(ar,eng)+'</button>').join('')+'</div>';root.onclick=e=>{const b=e.target.closest('[data-tab]');if(b)open(b.dataset.tab).catch(e=>showCartNotice(e.message))};}
 async function handle(b){const action=b.dataset.cAct,id=b.dataset.id;
  if(action==='close')return close();if(action==='login'){close();if(typeof openAccount==='function')openAccount();return;}
  if(action==='tab')return render(b.dataset.tab);if(action==='gift-find')return giftFind();
  if(action==='new-list')return newList();if(action==='new-poll')return newList('poll');
  if(action==='pick-for-list'){listDraft={kind:$('#lfNewKind').value,title:$('#lfNewTitle').value,alerts:$('#lfNewAlerts').checked};return productPicker('selection',{kind:listDraft.kind});}
  if(action==='pick-compare'){if(selected.length>=3)throw Error(t('المقارنة حتى ثلاث قطع؛ أزيلي قطعة أولًا','Compare up to three items; remove one first'));return productPicker('compare');}
  if(action==='choose-product')return chooseProduct(id);if(action==='confirm-product')return confirmProduct();if(action==='save-list')return saveList();
  if(action==='remove-selection'||action==='remove-compare'){selected.splice(Number(b.dataset.index),1);persist('lf_community_selection',selected);return action==='remove-compare'?compare():newList($('#lfNewKind')?.value||'wishlist');}
  if(action==='view-list')return viewShared(b.dataset.token);
  if(action==='share-list')return share(t('هاي اختياراتي من Ladies First 🌸','My Ladies First picks 🌸'),listUrl(b.dataset.token));
  if(action==='share-referral')return share(t('اختاري اللي بتحبيه من Ladies First، وإلك خصم لأول طلب 🌸','Find your favorites at Ladies First and get a first-order discount 🌸'),b.dataset.url);
  if(action==='share-product'||action==='hint-product'){const p=product(id),message=action==='hint-product'?t('وفّرت عليك حيرة الهدية 😉 هاي القطعة عجبتني: ','Here’s a little gift hint 😉 I love this: '):t('شوفي هالقطعة من Ladies First 🌸 ','Take a look at this Ladies First pick 🌸 ');return share(message+title(p),shareUrl(id));}
  if(action==='story-product'){await open('gifts');return story(Number(id));}if(action==='share-story'){const canvas=$('#lfStoryCanvas');const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error(t('تعذر تجهيز الصورة','Could not prepare the image'));return share($('#lfStoryCaption').value,shareUrl(window.LFCommunity.storyProduct),new File([blob],'Ladies-First-Story.png',{type:'image/png'}));}
  if(action==='copy-product-link')return copy(shareUrl(id));
  if(action==='save-product'||action==='compare-product'){const p=product(id),name=typeof selectedVariant==='function'?selectedVariant(Number(id)):'',variantId=options(p).find(v=>(v.name||v.color)===name)?.id||firstChoice(p);if(!selected.some(i=>i.productId===Number(id)&&String(i.variantId||'')===String(variantId||''))){if(action==='compare-product'&&selected.length>=3)throw Error(t('أزيلي اختيارًا قبل إضافة قطعة رابعة','Remove a choice before adding a fourth item'));selected.push({productId:Number(id),variantId,quantity:1});}persist('lf_community_selection',selected);await open(action==='compare-product'?'compare':'lists');return action==='save-product'?newList():compare();}
  if(action==='product'){close();if(typeof openProduct==='function')openProduct(Number(id));return;}
  if(action==='product-reviews'){await open('reviews');return reviews(Number(id));}
  if(action==='write-review')return writeReview(Number(id));
  if(action==='submit-review'){const body={productId:window.LFCommunity.reviewProduct,rating:Number($('#lfReviewRating').value),displayName:$('#lfReviewName').value,body:$('#lfReviewBody').value,consent:$('#lfReviewConsent').checked,image:await photoData($('#lfReviewImage').files[0])};await api('/reviews','POST',body);return content('<p class="lf-c-success">'+t('وصلت تجربتك للمراجعة. تقدري تتابعي حالتها من «تقييماتي».','Your review was submitted. Track its status under My reviews.')+'</p>'+button('my-reviews',t('تقييماتي','My reviews')));}
  if(action==='my-reviews'){if(!needAccount())return;const r=await api('/my-reviews');return content(r.reviews.map(x=>'<article class="lf-c-card"><p>'+'★'.repeat(x.rating)+' — '+E({pending:t('قيد المراجعة','Pending'),approved:t('منشور','Published'),rejected:t('لم يُنشر','Not published')}[x.status])+'</p><p>'+E(x.body)+'</p><small>'+E(x.note)+'</small>'+button('delete-review',t('سحب الموافقة وحذف تجربتي','Withdraw consent and delete'),'data-id="'+x.id+'"')+'</article>').join('')||'<p class="lf-c-empty">'+t('ما عندك تقييمات بعد.','No reviews yet.')+'</p>');}
  if(action==='delete-review'){await api('/reviews/'+id,'DELETE');return handle({dataset:{cAct:'my-reviews'}});}
  if(action==='share-review'){const u=new URL('/',location.origin);u.searchParams.set('review',id);return share(t('تجربة شراء من Ladies First 🌸','A Ladies First customer story 🌸'),u.href);}
  if(action==='gift-swap')return productPicker('swap',{index:Number(b.dataset.index),item:Number(b.dataset.item)});
  if(action==='gift-buy'){const q=window.LFCommunity.giftBundles[Number(b.dataset.index)],gift={occasion:'surprise',occasionLabel:giftForm.occasion,title:t('هدية إلك','A gift for you'),file:'card-05.jpg',gender:giftForm.gender,recipient:giftForm.recipient,sender:giftForm.sender,message:giftForm.message,side:'right'};return installCart(q.items,{title:t('هدية بميزانيتي','Gift on a budget'),region:giftForm.region},gift);}
  if(action==='add-group')return productPicker('group',{token:viewList.token});
  if(action==='add-existing')return productPicker('existing',{id:viewList.id,token:viewList.token});
  if(action==='delete-list-item'){await api('/shared/'+viewList.token+'/items/'+id,'DELETE',{visitorKey:visitor});return viewShared(viewList.token);}
  if(action==='vote'){const r=await api('/shared/'+viewList.token+'/vote','POST',{itemId:id,comment:$('#lfVoteComment')?.value||'',visitorKey:visitor});viewList={...r.list,own:viewList.own};renderShared();status(t('وصل صوتك 🌸','Your vote is in 🌸'));return;}
  if(action==='buy-list')return buyList();if(action==='delivery')return privateDelivery();
  if(action==='save-delivery'){await api('/lists/'+viewList.id+'/delivery','PUT',{name:$('#lfDeliveryName').value,phone:$('#lfDeliveryPhone').value,address:$('#lfDeliveryAddress').value,region:$('#lfDeliveryRegion').value,consent:$('#lfDeliveryConsent').checked});return viewShared(viewList.token);}
  if(action==='remove-delivery'){await api('/lists/'+viewList.id+'/delivery','PUT',{enabled:false});return viewShared(viewList.token);}
  if(action==='toggle-alerts'){await api('/lists/'+viewList.id,'PATCH',{alerts:!viewList.alerts});return viewShared(viewList.token);}
  if(action==='revoke-list'){if(!confirm(t('إلغاء هذه القائمة ورابطها؟','Revoke this list and its link?')))return;await api('/lists/'+viewList.id,'DELETE');return render('lists');}
  if(action==='group-split'){const items=viewList.items.filter(i=>i.available&&!i.claimed);if(!items.length)return;const r=await api('/quote','POST',{region:$('#lfGroupRegion').value,items});const names=[...new Set(items.map(i=>i.contributorId||'owner'))];$('#lfGroupSplit').innerHTML='<p class="lf-c-note">'+t('التوصيل: ','Delivery: ')+M(r.quote.shipping)+' ÷ '+names.length+' = '+M(r.quote.shipping/names.length)+' '+t('لكل مشاركة','per person')+'</p>';return;}
  if(action==='compare-advice'){const budget=Number($('#lfCompareBudget').value),occasion=$('#lfCompareOccasion').value;const candidates=selected.slice(0,3).map(i=>({i,p:product(i.productId)})).filter(x=>x.p&&stock(x.p,x.i.variantId)>0&&itemPrice(x.p,x.i.variantId)<=budget).sort((a,b)=>Number(String(b.p.metadata?.occasionTags||'').includes(occasion))-Number(String(a.p.metadata?.occasionTags||'').includes(occasion))||itemPrice(a.p,a.i.variantId)-itemPrice(b.p,b.i.variantId));$('#lfCompareAdvice').innerHTML='<p class="lf-c-note">'+(candidates.length?t('نايا: أقرب اختيار حسب الميزانية والمعلومات المسجلة هو ','Naia: Based on your budget and the recorded details, my closest pick is ')+E(title(candidates[0].p))+'. '+t('الخامة والملاءمة تعتمد على تفاصيل الصنف؛ ما بخمّن معلومات مش مسجلة.','Material and suitability depend on the product details; I do not infer missing information.'):t('ما في اختيار متوفر ضمن هالميزانية. جرّبي ميزانية أو قطع ثانية.','No available choice fits this budget. Try another budget or different items.'))+'</p>';return;}
  if(action==='closet-hide'){await api('/closet/'+id,'PATCH',{hidden:b.dataset.hidden==='true'});return closet();}
  if(action==='read-notifications'){await api('/notifications/read','POST',{});return notifications();}
 }
 async function boot(){
  const incoming=new URL(location.href).searchParams.get('ref');if(incoming&&/^[a-f0-9]{18}$/.test(incoming))persist('lf_referral_incoming',{code:incoming,expires:Date.now()+30*86400000});
  try{cfg=await api('/config');if(!cfg.settings.enabled)return;await refresh();mount();if(auth()){try{refCode=(await api('/referral')).code;}catch{}}
   if(typeof window.openProduct==='function'){const original=window.openProduct;window.openProduct=function(id){const result=original(id);productTools(id);return result;};}
   if(typeof window.renderCart==='function'){const original=window.renderCart;window.renderCart=function(){const result=original();decorateCart();refreshReferral();return result;};}
   if(typeof window.renderAccountContent==='function'){
    const original=window.renderAccountContent;window.renderAccountContent=function(){const result=original();const root=$('#accountContent');if(root&&auth()&&!$('#lfCommunityAccount')){const b=document.createElement('button');b.id='lfCommunityAccount';b.className='lf-c-btn';b.textContent=t('هداياي، قوائمي، خزانتي وتنبيهاتي','My gifts, lists, wardrobe and alerts');b.onclick=()=>{if(typeof closeAccount==='function')closeAccount();open('lists')};root.prepend(b);}return result;};
   }
   let noticeBusy=false;
   async function checkNotices(){if(noticeBusy||!auth()||document.hidden)return;noticeBusy=true;try{const r=await api('/notifications');const count=r.notifications.filter(n=>!n.seen).length;let b=$('#lfCommunityNotices');if(!b){b=document.createElement('button');b.id='lfCommunityNotices';b.className='lf-c-btn';b.onclick=()=>open('notifications');$('#lfCommunityHome')?.append(b);}b.textContent=t('تنبيهاتي','My alerts')+(count?' ('+count+')':'');}catch{}finally{noticeBusy=false;}}
   checkNotices();setInterval(checkNotices,120000);window.addEventListener('focus',checkNotices);
   const u=new URL(location.href),token=u.searchParams.get('list'),productId=Number(u.searchParams.get('product'));
   if(token&&/^[a-f0-9]{36}$/.test(token))await viewShared(token);else if(u.searchParams.has('review')){await open('reviews');await reviews(null,u.searchParams.get('review'));}else if(productId>0){for(let i=0;i<20&&!products.some(p=>Number(p.id)===productId);i++)await new Promise(r=>setTimeout(r,250));if(products.some(p=>Number(p.id)===productId))openProduct(productId);}
  }catch(e){console.warn('[Community]',e.message);}
 }
 window.LFCommunity={open,share,productTools,referralCoupon,orderExtras:()=>({...(checkout?.token?{community:{token:checkout.token,itemIds:checkout.itemIds,privateDelivery:checkout.privateDelivery===true}}:{}),referralCode:loadLocal('lf_referral_incoming',null)?.code||null}),orderComplete:()=>{checkout=null;persist('lf_community_checkout',null);referralCache=null;referralKey='';},giftBundles:[]};
 document.addEventListener('lf:languagechange',()=>{mount();if(panel&&!panel.hidden){if(viewList)renderShared();else render(currentTab).catch(e=>status(e.message))}});
 boot();
})();
